from calendar import isleap
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CONVENTIONS = frozenset(("30/360_US", "30E/360", "ACT/365F", "ACT/ACT_ISDA"))
_TEN_PLACES = Decimal("0.0000000001")
_CENT = Decimal("0.01")
_HUNDRED = Decimal("100")


def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError("date must be a string in YYYY-MM-DD format")
    if len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError("date must be in YYYY-MM-DD format")
    digits = value[0:4] + value[5:7] + value[8:10]
    for ch in digits:
        if ch < "0" or ch > "9":
            raise ValueError("date must be in YYYY-MM-DD format")
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError("invalid calendar date") from None


def _validate_convention(value):
    if not isinstance(value, str) or value not in _CONVENTIONS:
        raise ValueError("invalid day-count convention")
    return value


def _parse_principal(value):
    if not isinstance(value, str):
        raise ValueError("principal must be a string")
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("invalid principal") from None
    if not parsed.is_finite() or parsed < 0:
        raise ValueError("invalid principal")
    if parsed.as_tuple().exponent < -2:
        raise ValueError("principal must have at most 2 decimal places")
    return parsed


def _parse_rate(value):
    if not isinstance(value, str):
        raise ValueError("annual_rate_percent must be a string")
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError("invalid annual_rate_percent") from None
    if not parsed.is_finite() or parsed < 0 or parsed > _HUNDRED:
        raise ValueError("invalid annual_rate_percent")
    return parsed


def _is_last_day_of_february(d):
    if d.month != 2:
        return False
    return d.day == (29 if isleap(d.year) else 28)


def _unrounded_fraction(start_date, end_date, convention):
    with localcontext() as ctx:
        ctx.prec = 50
        if convention == "ACT/365F":
            return Decimal((end_date - start_date).days) / Decimal(365)
        if convention == "ACT/ACT_ISDA":
            total = Decimal(0)
            cursor = start_date
            while cursor < end_date:
                if cursor.year == 9999:
                    segment_end = end_date
                else:
                    next_year = date(cursor.year + 1, 1, 1)
                    segment_end = end_date if end_date < next_year else next_year
                days = (segment_end - cursor).days
                denominator = Decimal(366 if isleap(cursor.year) else 365)
                total += Decimal(days) / denominator
                cursor = segment_end
            return total
        if convention == "30/360_US":
            d1 = start_date.day
            d2 = end_date.day
            start_last_feb = _is_last_day_of_february(start_date)
            end_last_feb = _is_last_day_of_february(end_date)
            if start_last_feb:
                d1 = 30
            if end_last_feb and start_last_feb:
                d2 = 30
            if start_date.day == 31:
                d1 = 30
            if end_date.day == 31 and d1 >= 30:
                d2 = 30
            days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (d2 - d1)
            return Decimal(days) / Decimal(360)
        # 30E/360
        d1 = min(start_date.day, 30)
        d2 = min(end_date.day, 30)
        days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (d2 - d1)
        return Decimal(days) / Decimal(360)


def day_count_fraction(start: str, end: str, convention: str) -> Decimal:
    start_date = _parse_date(start)
    end_date = _parse_date(end)
    _validate_convention(convention)
    if end_date < start_date:
        raise ValueError("end must not be before start")
    fraction = _unrounded_fraction(start_date, end_date, convention)
    with localcontext() as ctx:
        ctx.prec = 50
        return fraction.quantize(_TEN_PLACES, rounding=ROUND_HALF_UP)


def accrued_interest(principal: str, annual_rate_percent: str, start: str, end: str, convention: str) -> Decimal:
    principal_value = _parse_principal(principal)
    rate_value = _parse_rate(annual_rate_percent)
    start_date = _parse_date(start)
    end_date = _parse_date(end)
    _validate_convention(convention)
    if end_date < start_date:
        raise ValueError("end must not be before start")
    fraction = _unrounded_fraction(start_date, end_date, convention)
    with localcontext() as ctx:
        ctx.prec = 50
        result = principal_value * (rate_value / _HUNDRED) * fraction
        return result.quantize(_CENT, rounding=ROUND_HALF_UP)
